// Minimal functional harness to validate game mechanics
const W = 1280, H = 720, ROOM_W = 760, ROOM_H = 520, ROOM_X = (W-ROOM_W)/2, ROOM_Y = 110;
const C = { cyan:'#00f0ff', mag:'#ff00ff', yel:'#ffe800', grn:'#0aff88', org:'#ff8800', red:'#ff3333', wht:'#ffffff', panel:'#0f0f1a', line:'#1a1a2e', dim:'#444466' };

const TASKS=['SLIME','PIPES','GRAV','VAC'];
function createTask(type){ switch(type){
 case 'SLIME': return new TaskSlime(ROOM_W,ROOM_H);
 case 'PIPES': return new TaskPipes(ROOM_W,ROOM_H);
 case 'GRAV': return new TaskGrav(ROOM_W,ROOM_H);
 case 'VAC': return new TaskVac(ROOM_W,ROOM_H);
}}
// recreate classes by re-reading source is heavy; instead copy minimal versions inline:

class Particle{constructor(x,y,color){this.x=x;this.y=y;const a=Math.random()*Math.PI*2;s=1.5+Math.random()*4;this.vx=Math.cos(a)*s;this.vy=Math.sin(a)*s;this.life=1;this.maxLife=0.35+Math.random()*0.5;this.color=color;this.size=2+Math.random()*4;}update(dt){this.x+=this.vx*60*dt;this.y+=this.vy*60*dt;this.vx*=0.92;this.vy*=0.92;this.life-=dt/this.maxLife;}}
const Particles={arr:[],emit(){},update(dt){for(let i=this.arr.length-1;i>=0;i--){this.arr[i].update(dt);if(this.arr[i].life<=0)this.arr.splice(i,1);}}};

class Task{constructor(type,rw,rh){this.type=type;this.complete=false;this.fail=false;this.timer=15;this.rw=rw;this.rh=rh;}update(dt){this.timer-=dt;if(this.timer<=0)this.fail=true;}draw(){}}
class TaskSlime extends Task{
 constructor(rw,rh){super('SLIME',rw,rh);this.blobs=[];for(let i=0;i<5;i++)this.blobs.push({x:120+Math.random()*(rw-240),y:120+Math.random()*(rh-240),r:24+Math.random()*16,vx:(Math.random()-0.5)*20,vy:(Math.random()-0.5)*20,contained:false});}
 update(dt){super.update(dt);this.blobs.forEach(b=>{if(b.contained)return;b.x+=b.vx*dt;b.y+=b.vy*dt;});}
 press(x,y,ox,oy){for(const b of this.blobs){if(b.contained)continue;const dx=x-(ox+b.x),dy=y-(oy+b.y);if(dx*dx+dy*dy<b.r*b.r){b.contained=true;if(this.blobs.every(b=>b.contained)){this.complete=true;return{ok:true,done:true};}return{ok:true,done:false};}}return{ok:false,done:false};}}
}
class TaskPipes extends Task{
 constructor(rw,rh){super('PIPES',rw,rh);this.pairs=[];const cols=['#00f0ff','#ff00ff','#ffe800','#0aff88','#ff8800'];const used=[];for(let i=0;i<4;i++){let col;do{col=cols[Math.floor(Math.random()*cols.length)];}while(used.includes(col));used.push(col);this.pairs.push({color:col,left:{x:90,y:140+i*95,done:false},right:{x:rw-90,y:140+i*95,done:false},connected:false});}const ys=this.pairs.map(p=>p.right.y).sort(()=>Math.random()-0.5);this.pairs.forEach((p,i)=>{p.right.y=ys[i];});this.selected=null;}
 press(x,y,ox,oy){const side=x<ox+this.rw/2?'left':'right';let hit=null;for(const p of this.pairs){if(p.connected)continue;const pt=side==='left'?p.left:p.right;const dx=x-(ox+pt.x),dy=y-(oy+pt.y);if(dx*dx+dy*dy<22*22){hit={p,pt,side};break;}}if(!hit)return{ok:false,done:false};const{p,side:s}=hit;if(s==='left'){this.selected={x:p.left.x,y:p.left.y,color:p.color};return{ok:true,done:false};}else{if(!this.selected)return{ok:true,done:false};if(this.selected.color===p.color){p.connected=true;this.selected=null;if(this.pairs.every(p=>p.connected)){this.complete=true;return{ok:true,done:true};}return{ok:true,done:false};}else{this.selected=null;return{ok:false,done:false};}}}}
}
class TaskGrav extends Task{
 constructor(rw,rh){super('GRAV',rw,rh);this.left={v:30,target:40+Math.random()*20,zone:40+Math.random()*20};this.right={v:70,target:60+Math.random()*20,zone:60+Math.random()*20};this.inZoneTime=0;this.levers=[{x:150,y:rh-90,dl:-10,dr:6},{x:300,y:rh-90,dl:6,dr:-10},{x:460,y:rh-90,dl:-6,dr:10},{x:620,y:rh-90,dl:10,dr:-6}];}
 update(dt){super.update(dt);const lOk=Math.abs(this.left.v-this.left.zone)<8;const rOk=Math.abs(this.right.v-this.right.zone)<8;if(lOk&&rOk){this.inZoneTime+=dt;if(this.inZoneTime>=0.7)this.complete=true;}else this.inZoneTime=0;}
 press(x,y,ox,oy){for(const l of this.levers){const dx=x-(ox+l.x),dy=y-(oy+l.y);if(dx*dx+dy*dy<60*60){this.left.v=Math.max(0,Math.min(100,this.left.v+l.dl));this.right.v=Math.max(0,Math.min(100,this.right.v+l.dr));if(Math.abs(this.left.v-this.left.zone)<8&&Math.abs(this.right.v-this.right.zone)<8){this.inZoneTime+=0.2;if(this.inZoneTime>=0.7)this.complete=true;}return{ok:true,done:this.complete};}}return{ok:false,done:false};}}
class TaskVac extends Task{
 constructor(rw,rh){super('VAC',rw,rh);this.debris=[];for(let i=0;i<8;i++)this.debris.push({x:80+Math.random()*(rw-160),y:80+Math.random()*(rh-160),r:5+Math.random()*4});}
 press(x,y,ox,oy){const nx=x-ox,ny=y-oy;let removed=0;for(let i=this.debris.length-1;i>=0;i--){const d=this.debris[i];const dx=d.x-nx,dy=d.y-ny;if(dx*dx+dy*dy<(36+d.r)*(36+d.r)){this.debris.splice(i,1);removed++;}}if(removed>0){if(this.debris.length===0){this.complete=true;return{ok:true,done:true};}return{ok:true,done:false};}return{ok:false,done:false};}}

let failures=0;
function assert(cond,msg){if(!cond){console.log('FAIL:',msg);failures++;}else console.log('ok:',msg);}

// 1. Slime completion
let t=new TaskSlime(ROOM_W,ROOM_H);
let blobsCleared=0;
for(const b of t.blobs){let r=t.press(b.x,b.y,0,0);assert(r.ok,'slime tap ok');if(r.done)blobsCleared++;}
assert(t.complete,'slime task complete after all blobs');
assert(blobsCleared===1,'slime done fires once');

// 2. Pipes completion
t=new TaskPipes(ROOM_W,ROOM_H);
let conn=0;let bad=0;
for(const p of t.pairs){let r=t.press(p.left.x,p.left.y,0,0);assert(r.ok&&!r.done,'pipe left select');r=t.press(p.right.x,p.right.y,0,0);if(r.ok)conn++;else bad++;}
assert(t.complete&&bad===0,'pipes all matched complete');

// 3. Vacuum completion
t=new TaskVac(ROOM_W,ROOM_H);
let clicked=0;
while(t.debris.length>0){const d=t.debris[0];let r=t.press(d.x,d.y,0,0);assert(r.ok,'vac suck');clicked++;}
assert(t.complete,'vac complete after all debris');

// 4. Game loop / streak / focus
class Game{constructor(){this.state='PLAYING';this.shiftTime=60;this.roomTime=20;this.score=0;this.integrity=3;this.streak=0;this.focus=false;this.focusTime=0;this.room=[createTask('SLIME')];this.nextModAt=20;this.modifier=null;this.modTime=0;this.flash=0;}
 actionOk(){this.streak++;this.score+=50;if(this.streak>=5){this.focus=true;this.focusTime=7;this.streak=0;}}
 actionBad(){this.streak=0;}}
let g=new Game();
const active=g.room[0];
for(const b of active.blobs){g.actionOk();active.press(b.x,b.y,ROOM_X,ROOM_Y);}
assert(active.complete,'room task complete');
assert(g.streak===0,'streak reset after focus trigger');
assert(g.focus===true,'focus triggered at streak 5');
assert(g.score===250,'score: 5 actions*50');
console.log('--- failures:',failures);

