const Particles={arr:[],emit(){},update(dt){for(let i=this.arr.length-1;i>=0;i--){this.arr[i].update(dt);if(this.arr[i].life<=0)this.arr.splice(i,1);}},draw(){}};
const Input={x:0,y:0,down:false,justDown:false,justUp:false};
