// Functional harness using the REAL game classes from chaos-janitor.html
const fs = require('fs');
const src = fs.readFileSync('/home/runner/work/PlayGround/PlayGround/chaos-janitor.html','utf8');
const m = src.match(/<script>([\s\S]*)<\/script>/);
if(!m){console.error('no script');process.exit(1);}
let js = m[1];

// real stub globals (assigned to globalThis so eval'd code can read them)
globalThis.ctx = {save(){},restore(){},translate(){},fillStyle:null,fillRect(){},globalAlpha:1,beginPath(){},arc(){},fill(){},stroke(){},strokeStyle:null,lineWidth:1,lineCap:'round',shadowBlur:0,shadowColor:'',fillText(){},textBaseline:'',textAlign:'',strokeRect(){}};
globalThis.canvas = {addEventListener(){},getBoundingClientRect(){return{left:0,top:0,width:1280,height:720};}};
globalThis.document = {addEventListener(){},body:{addEventListener(){}},createElement(){return globalThis.canvas;}};
globalThis.window = {addEventListener(){},AudioContext:function(){this.currentTime=0;this.createGain=function(){return{g:{setValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){}};};this.createOscillator=function(){return{frequency:{setValueAtTime(){},exponentialRampToValueAtTime(){}},type:'',connect(){},start(){},stop(){}};};},resolution(){return Promise.resolve();}};
globalThis.window.AudioContext = globalThis.window.AudioContext;
globalThis.Audio = {ctx:null,master:null,init(){return Promise.resolve();},_tone(){},click(){},ok(){},fail(){},focus(){},roomDone(){},modifier(){},taskFail(){},tick(){}};
globalThis.Music = {active:false,setFocus(){},start(){},stop(){},update(){}};
globalThis.W = 1280; globalThis.H = 720;
globalThis.rect = function(){};
globalThis.line = function(){};
globalThis.circle = function(){};
globalThis.text = function(){};
globalThis.Particles = {arr:[],emit(){},update(dt){for(let i=this.arr.length-1;i>=0;i--){this.arr[i].update(dt);if(this.arr[i].life<=0)this.arr.splice(i,1);}},draw(){}};
globalThis.Input = {x:0,y:0,down:false,justDown:false,justUp:false};
globalThis.ROOM_W = 760; globalThis.ROOM_H = 520;
globalThis.ROOM_X = (globalThis.W-globalThis.ROOM_W)/2;
globalThis.ROOM_Y = 110;
globalThis.TASKS = ['SLIME','PIPES','GRAV','VAC'];

js = js.replace(/<\/script>.*/s,'');
// hoist class declarations to globalThis so tests can access them
js = js.replace(/\bclass\s+(\w+)\b/g, (m,name)=> 'globalThis.'+name+' = class '+name);

let failures=0;
function assert(cond,msg){if(!cond){console.log('FAIL:',msg);failures++;}else console.log('ok:',msg);}
eval(js);

const TaskSlime=globalThis.TaskSlime, TaskPipes=globalThis.TaskPipes, TaskGrav=globalThis.TaskGrav, TaskVac=globalThis.TaskVac;
const ROOM_W=760,ROOM_H=520;

// 1. Slime completion
let t=new TaskSlime(ROOM_W,ROOM_H);
let blobsCleared=0;
for(const b of t.blobs){let r=t.press(b.x,b.y,0,0);assert(r.ok===true,'slime tap ok');if(r.done)blobsCleared++;}
assert(t.complete===true,'slime task complete after all blobs');
assert(blobsCleared===1,'slime done fires once');

// 2. Pipes completion
t=new TaskPipes(ROOM_W,ROOM_H);
let bad=0;
for(const p of t.pairs){let r=t.press(p.left.x,p.left.y,0,0);assert(r.ok===true&&r.done===false,'pipe left select');r=t.press(p.right.x,p.right.y,0,0);if(!r.ok)bad++;}
assert(t.complete===true&&bad===0,'pipes all matched complete');

// 3. Vacuum completion
t=new TaskVac(ROOM_W,ROOM_H);
while(t.debris.length>0){const d=t.debris[0];let r=t.press(d.x,d.y,0,0);assert(r.ok===true,'vac suck');}
assert(t.complete===true,'vac complete after all debris');

// 4. Streak -> Focus
let streak=0,score=0,focus=false;
function actionOk(){streak++;score+=50;if(streak>=5){focus=true;streak=0;}}
for(let i=0;i<5;i++)actionOk();
assert(focus===true,'focus triggered at streak 5');
assert(streak===0,'streak reset after focus');
assert(score===250,'score 5*50 = '+score);

// 5. Room timer expiry -> integrity loss
let integrity=3;
const a2=new TaskSlime(ROOM_W,ROOM_H); a2.timer=0; a2.update(0.01);
assert(a2.fail===true,'slime timer expiry -> fail');
if(a2.fail){integrity--;}
assert(integrity===2,'integrity 3->2 on room timeout');

// 6. Modifier application
const MODS=[{id:'zeroG'},{id:'inv'},{id:'slip'},{id:'dark'},{id:'fast'}];
let mod=MODS[Math.floor(Math.random()*MODS.length)];
assert(mod.id in {zeroG:1,inv:1,slip:1,dark:1,fast:1},'random modifier valid id: '+mod.id);

console.log('--- total failures:',failures);
process.exit(failures>0?1:0);

